# filename: scripts/verify_stream.py
"""Cards [11] Kinesis and [12] feature updater (poller/Lambda standing in for Flink): 'Done when' checks.
Sends 6 quick payments for a brand-new test card, then measures:
  [11] time until each payment's record is readable on the stream, plus retention
  [12] time until card_features shows txn_count_5m = 6, and that it STAYS 6 (no double counting)
Run inside the setup container (it can reach LocalStack and HAProxy by service name):
  docker compose run --rm --no-deps setup python -m scripts.verify_stream"""
import argparse, json, time, uuid

from common.aws import client
from scripts.stepup_e2e import payment, post      # reuse the same payment builder as the step-up test

STREAM, TABLE, N = "payment-events", "card_features", 6


def latest_iterators(kin):
    """Start at 'now' on every shard BEFORE sending, so we only see our own records."""
    shards = kin.list_shards(StreamName=STREAM)["Shards"]
    return [kin.get_shard_iterator(StreamName=STREAM, ShardId=s["ShardId"],
                                   ShardIteratorType="LATEST")["ShardIterator"] for s in shards]


def read_shards(kin, its, sent, arrived):
    """One pass over every shard; records how long after its reply each of our payments appeared."""
    nxt = []
    for it in its:
        r = kin.get_records(ShardIterator=it, Limit=1000)
        for rec in r["Records"]:
            try:
                d = json.loads(rec["Data"])
            except ValueError:
                continue                                   # not JSON: not one of ours
            tid = d.get("event_id") or d.get("transaction_id")
            if tid in sent and tid not in arrived:
                arrived[tid] = time.monotonic() - sent[tid]
        if r.get("NextShardIterator"):                     # None only if the shard was closed
            nxt.append(r["NextShardIterator"])
    return nxt


def card_row(ddb, tok):
    return ddb.get_item(TableName=TABLE, Key={"card_token": {"S": tok}}).get("Item", {})


def count_of(row):
    return int(row.get("txn_count_5m", {}).get("N", 0))


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--url", default="http://haproxy:8080/v1/decide")   # inside Docker: service name, not localhost
    p.add_argument("--cards", default="/data/cards.jsonl")
    p.add_argument("--within-s", type=float, default=5, help="[12] 'within seconds' pass mark")
    a = p.parse_args()

    with open(a.cards) as fh:
        base = json.loads(fh.readline())                   # synthetic card from the generator, never real data
    tok = f"tok_verify_{uuid.uuid4().hex[:12]}"             # fresh synthetic token: no old history
    kin, ddb = client("kinesis"), client("dynamodb")
    its = latest_iterators(kin)

    sent = {}                                              # transaction id -> time its reply arrived
    for _ in range(N):
        body = payment(base, "dev_verify", 10)             # CHANGED: build from the real card row...
        body["card_token"] = tok                           # CHANGED: ...then force the test token onto the payment
        tid = body["transaction_id"]                       # CHANGED: field name confirmed by your error output
        if tid in sent:                                    # NEW: a reused id would be deduped and the count stuck at 1
            raise SystemExit("payment() returned the same transaction_id twice: it must be unique per call")
        status, _ = post(a.url, body)
        if status != 200:
            raise SystemExit(f"/v1/decide returned {status}")
        sent[tid] = time.monotonic()
    t_last = time.monotonic()

    arrived, count_s, seen_counts = {}, None, []
    deadline = t_last + 30
    while time.monotonic() < deadline and (len(arrived) < N or count_s is None):
        if len(arrived) < N:
            its = read_shards(kin, its, sent, arrived)
        if count_s is None:
            c = count_of(card_row(ddb, tok))
            if not seen_counts or seen_counts[-1] != c:
                seen_counts.append(c)                      # shows whether updates come one by one or batched
            if c >= N:
                count_s = time.monotonic() - t_last
        time.sleep(0.1)
    time.sleep(3)                                          # duplicate deliveries must not push it past 6
    row = card_row(ddb, tok)

    summ = kin.describe_stream_summary(StreamName=STREAM)["StreamDescriptionSummary"]
    retention = summ["RetentionPeriodHours"]
    mode = summ.get("StreamModeDetails", {}).get("StreamMode", "not reported")
    worst = max(arrived.values(), default=float("inf"))

    print(f"test card {tok}   stream mode {mode}   retention {retention} h")
    print(f"[11] records on stream {len(arrived)}/{N}   worst delay {worst:.2f} s")
    print(f"[12] counts seen {seen_counts}   reached {N} after "
          + (f"{count_s:.1f} s" if count_s is not None else "never (30 s)")
          + f"   final {count_of(row)}   updated_at {row.get('updated_at', {}).get('N') or row.get('updated_at')}")
    checks = [("[11] every record reached the stream", len(arrived) == N),
              ("[11] every record within 1 s", worst <= 1.0),
              ("[11] retention 24 h or more", retention >= 24),
              (f"[12] txn_count_5m reached {N} within {a.within_s:.0f} s",
               count_s is not None and count_s <= a.within_s),
              (f"[12] count stays exactly {N} (no double counting)", count_of(row) == N),
              ("[12] updated_at is set", "updated_at" in row)]
    for name, ok in checks:
        print(("PASS " if ok else "FAIL ") + name)


if __name__ == "__main__":
    main()
